--Q1. What is the total revenue generated by male vs. female customers?
select gender, SUM(purchase_amount_usd) as revenue
from customer
group by gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 
select customer_id, purchase_amount_usd
from customer
where discount_applied = 'Yes'
AND purchase_amount_usd > (select AVG(purchase_amount_usd) from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased as product, ROUND(AVG(review_rating)::numeric, 2) as avg_rating
from customer
group by item_purchased
order by avg_rating desc
limit 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select ROUND(AVG(purchase_amount_usd)::numeric, 2) as average_purchase_amount, shipping_type
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY average_purchase_amount desc;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
select 
        subscription_status, 
        ROUND(AVG(purchase_amount_usd):: numeric, 2) as average_spend, 
        SUM(purchase_amount_usd) as total_revenue, 
        COUNT(customer_id) as jumlah_pelanggan
from customer
GROUP BY subscription_status
ORDER BY total_revenue desc;

-- jawaban versi 2
SELECT subscription_status,
       COUNT(customer_id) AS total_customers,
       ROUND(AVG(purchase_amount_usd),2) AS avg_spend,
       ROUND(SUM(purchase_amount_usd),2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue,avg_spend DESC;


--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased as product, 
        ROUND((SUM(CASE WHEN discount_applied = 'Yes' THEN 1.0 ELSE 0 END) / COUNT(*)) * 100, 2) AS persentase_pembelian
from customer
GROUP BY item_purchased
ORDER BY persentase_pembelian DESC
limit 5;

--VERSI 2
SELECT item_purchased,
       ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
SELECT customer_id, previous_purchases as jumlah_pembelian,
        (CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
        END) AS loyalitas
FROM customer;

-- versi 2 menggunakan CTE (common table expression)
WITH customer_type AS(
        SELECT customer_id,
        CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
        END AS loyalitas
        from customer
)
select loyalitas,
        COUNT(*) AS total_customers
from customer_type
GROUP BY loyalitas;


--Q8. What are the top 3 most purchased products within each category? 
-- mengambil item dan kategori serta jumlah pesanan
SELECT 
    category,
    item_purchased AS item, 
    COUNT(*) AS total_orders
FROM customer
GROUP BY category, item_purchased;

-- menambahkan window function untuk ranking
SELECT 
    category,
    item_purchased AS item, 
    COUNT(*) AS total_orders,
    ROW_NUMBER() OVER (
        PARTITION BY category 
        ORDER BY COUNT(*) DESC
    ) AS item_rank
FROM customer
GROUP BY category, item_purchased;

-- menambahkan CTE untuk filter top 3
WITH item_counts AS (
    SELECT 
        category,
        item_purchased AS item, 
        COUNT(*) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category 
            ORDER BY COUNT(*) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT 
    category,
    item,
    total_orders,
    item_rank
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select customer_id, subscription_status,
        CASE
        WHEN previous_purchases > 5 THEN 'repeat buyers'
        ELSE 'regular buyers'
        END AS customer_type
from customer;

--FILTER
WITH buyers_type AS (
        select customer_id, subscription_status,
        CASE
        WHEN previous_purchases > 5 THEN 'repeat buyers'
        ELSE 'regular buyers'
        END AS customer_type
        from customer
)
SELECT subscription_status,
        count(*) AS total_customers
FROM buyers_type
WHERE customer_type = 'repeat buyers'
GROUP BY subscription_status;

-- simplified
SELECT 
    subscription_status,
    COUNT(*) AS total_repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. What is the revenue contribution of each age group? 
select SUM(purchase_amount_usd) as revenue, age_group
from customer
GROUP BY age_group
ORDER BY revenue DESC;